import {demo,execute,scoped,uid} from './core.js';import {cloudReady} from './config.js';
import * as spark from './spark.js';
let db;const mode=cloudReady?'live':'demo';
function database(){return new Promise((resolve,reject)=>{const q=indexedDB.open('packflow-spark-v2-'+mode,1);q.onupgradeneeded=()=>q.result.createObjectStore('kv');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
export async function init(){db=await database();if(!await get('state')&&mode==='demo')await put('state',demo());return mode;}
export function get(key){return new Promise((resolve,reject)=>{const q=db.transaction('kv').objectStore('kv').get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}export function put(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
export async function login(id,password){let actor;if(mode==='demo'){if(password!=='demo123')throw Error('Demo password: demo123');actor=(await get('state')).users.find(u=>u.id.toLowerCase()===id.toLowerCase()&&u.active);if(!actor)throw Error('ID not found.');}else{actor=await spark.login(id,password);await refresh(actor);}await put('session',actor);return actor;}
export async function logout(){if((await get('queue')||[]).length)throw Error('Upload pending submissions before signing out.');stopWatch?.();stopWatch=null;watcherId=null;clearTimeout(watchTimer);if(mode==='live')await spark.signout();await put('session',null);if(mode==='live')await put('state',null);}
export async function refresh(actor){if(mode==='live')await put('state',await spark.snapshot(actor));return view(actor);}export async function view(actor){const s=await get('state');const out=mode==='demo'?scoped(s,actor):s;if(mode==='demo'&&actor.role==='admin')out.accountJobs=await get('accountJobs')||[];return out;}
export async function send(actor,type,payload,options={}){const cmd={id:uid(),type,payload};if(['deliver','receive','loss'].includes(type)){if(type==='deliver'&&mode==='live'){const s=await get('state');payload.extraVersion=s.users.find(u=>u.id===payload.packerId)?.extraVersion;payload.items=payload.items.map(i=>({...i,rateVersion:s.products.find(p=>p.id===i.productId)?.rateVersion}));}const q=await get('queue')||[];q.push({cmd,actorId:actor.id,queuedAt:new Date().toISOString(),status:'queued'});await put('queue',q);if(navigator.onLine)await sync(actor);return;}if(!navigator.onLine)throw Error('Connect to confirm or administer records.');await dispatch(actor,cmd,options);}
async function dispatch(actor,cmd,options={}){if(mode==='demo')await put('state',execute(await get('state'),cmd,actor));else{await spark.dispatch(actor,cmd);if(!options.deferRefresh)await refresh(actor);}}
let syncing=false;export async function sync(actor){if(syncing||!navigator.onLine)return;syncing=true;try{const q=await get('queue')||[];for(const item of q){if(item.actorId!==actor.id||item.status==='uploaded')continue;try{if(mode==='live'){const resolved=await spark.issueResolution(item.cmd.id);if(resolved==='corrected'||resolved==='rejected'){item.status='uploaded';continue;}}await dispatch(actor,item.cmd);item.status='uploaded';delete item.error;}catch(e){item.status='needs-review';item.error=e.message;if(mode==='live')await spark.reportIssue(actor,item.cmd,e.message);}await put('queue',q);}await put('queue',q.filter(i=>i.status!=='uploaded'));}finally{syncing=false;}}
export async function resolveIssue(data){if(mode==='demo')throw Error('Cloud issues become available after setup.');return spark.resolveIssue(await get('session'),data);}
export async function accountAction(data){const actor=await get('session');if(mode==='demo'){if(data.action==='reveal')throw Error('Passwords cannot be viewed.');if(data.action==='reset'){const jobs=await get('accountJobs')||[];jobs.push({id:uid(),targetId:data.id,status:'pending',type:'reset'});await put('accountJobs',jobs);return {queued:true};}if(data.action==='save'){await put('state',execute(await get('state'),{id:uid(),type:'saveUser',payload:data.person},actor));return {ok:true};}}return spark.accountAction(actor,data);}
export async function reset(){if(mode!=='demo')throw Error('Demo only.');await put('state',demo());await put('queue',[]);}export const currentMode=()=>mode;
let watcherId=null,stopWatch=null,watchTimer;
export function watch(actor,onChange){if(mode!=='live'||watcherId===actor.id||!navigator.onLine)return;stopWatch?.();watcherId=actor.id;spark.watch(actor,()=>{clearTimeout(watchTimer);watchTimer=setTimeout(async()=>{try{await refresh(actor);onChange();}catch{}},300);}).then(stop=>{stopWatch=stop;}).catch(()=>{watcherId=null;});}

export async function provisionAccount(id,password,options={}){const actor=await get('session');if(mode!=='live')throw Error('Login provisioning is available in Firebase mode only.');return spark.provisionAccount(actor,id,password,options);}
